#include "analysis_io.h"
#include "archive_csv.h"
#include <sstream>
#include <iomanip>
#include <set>
namespace rs3d {
namespace {
using Columns=std::vector<std::string>;
std::string number(double v){std::ostringstream s;s.imbue(std::locale::classic());s<<std::setprecision(17)<<v;return s.str();}
std::string csv(const std::string&s){std::string out="\"";for(char c:s){if(c=='\"')out+='\"';out+=c=='\r'||c=='\n'?' ':c;}return out+'\"';}
std::string line(const Columns&names,const CsvRow*row=nullptr){std::string out;for(const auto&name:names){if(!out.empty())out+=',';out+=csv(row?row->at(name):name);}return out+'\n';}
CsvRow empty(const Columns&names){CsvRow row;for(const auto&name:names)row[name]="";return row;}
Columns poseNames(const std::string&prefix){Columns out;for(auto s:{"center_x","center_y","center_z","origin_x","origin_y","origin_z","qw","qx","qy","qz","vx","vy","vz","omega_x","omega_y","omega_z"})out.push_back(prefix+s);return out;}
void addPoseColumns(Columns&c){for(auto p:{"rock_","barrier_"}){auto names=poseNames(p);c.insert(c.end(),names.begin(),names.end());}}
Columns eventColumns(){Columns c{"trial_id","barrier_id","status","trial_status","time_lower","time_upper","step","substep","slop","impulse_threshold_Ns","dedup_tolerance_m","boundary_tolerance_m","representative_u","representative_v","cell_id","raw_point_count","face","reason"};addPoseColumns(c);return c;}
Columns pointColumns(){Columns c{"trial_id","point_id","dedup_group","world_x","world_y","world_z","local_x","local_y","local_z","normal_x","normal_y","normal_z","signed_gap_m","normal_impulse_Ns","ccd_fraction","method","candidate_source","confirmation","impulse_scope","face"};addPoseColumns(c);return c;}
const Columns events=eventColumns(),points=pointColumns();
void pose(CsvRow&r,const std::string&prefix,const ContactBodyPose&p){auto names=poseNames(prefix);double values[]{p.center.x,p.center.y,p.center.z,p.shapeOrigin.x,p.shapeOrigin.y,p.shapeOrigin.z,p.rotation.w,p.rotation.x,p.rotation.y,p.rotation.z,p.velocity.x,p.velocity.y,p.velocity.z,p.angularVelocity.x,p.angularVelocity.y,p.angularVelocity.z};for(size_t i=0;i<names.size();++i)r[names[i]]=number(values[i]);}
ContactBodyPose pose(const CsvRow&r,const std::string&prefix){auto names=poseNames(prefix);std::vector<double> v;for(const auto&n:names)v.push_back(archiveNumber(r.at(n)));ContactBodyPose p;p.center={v[0],v[1],v[2]};p.shapeOrigin={v[3],v[4],v[5]};p.rotation={v[6],v[7],v[8],v[9]};p.velocity={v[10],v[11],v[12]};p.angularVelocity={v[13],v[14],v[15]};p.rotation.matrix();return p;}
void require(bool v,const char*m){if(!v)throw std::runtime_error(m);}
StopReason stop(const std::string&s){for(int i=0;i<=int(StopReason::cancelled);++i)if(s==stopReasonName(StopReason(i)))return StopReason(i);throw std::runtime_error("invalid first-contact trial status");}
FirstContactStatus status(const std::string&s){for(int i=0;i<=int(FirstContactStatus::notRecorded);++i)if(s==firstContactStatusName(FirstContactStatus(i)))return FirstContactStatus(i);throw std::runtime_error("invalid first-contact status");}
ContactMethod method(const std::string&s){for(int i=0;i<=int(ContactMethod::resolvedCcd);++i)if(s==contactMethodName(ContactMethod(i)))return ContactMethod(i);throw std::runtime_error("invalid contact confirmation method");}
}
void writeAnalysisHeaders(const ArchiveWrite&write){write("barrier_first_contact.csv",line(events));write("barrier_first_contact_points.csv",line(points));}
void writeFirstContact(const FirstContactEvent&e,const ArchiveWrite&write){auto r=empty(events);r["trial_id"]=std::to_string(e.trialId);r["barrier_id"]=std::to_string(barrierObjectId);r["status"]=firstContactStatusName(e.status);r["trial_status"]=stopReasonName(e.trialStatus);r["reason"]=e.reason;r["slop"]=number(e.slop);r["impulse_threshold_Ns"]=number(e.impulseThreshold);r["dedup_tolerance_m"]=number(e.dedupTolerance);r["boundary_tolerance_m"]=number(e.boundaryTolerance);
    if(e.status==FirstContactStatus::hit){r["time_lower"]=number(e.timeLower);r["time_upper"]=number(e.timeUpper);r["step"]=std::to_string(e.step);r["substep"]=std::to_string(e.substep);r["representative_u"]=number(e.u);r["representative_v"]=number(e.v);r["cell_id"]=std::to_string(e.cell);r["raw_point_count"]=std::to_string(e.points.size());r["face"]=e.face;pose(r,"rock_",e.rock);pose(r,"barrier_",e.barrier);}
    write("barrier_first_contact.csv",line(events,&r));
    for(size_t i=0;i<e.points.size();++i){const auto&p=e.points[i];auto q=empty(points);q["trial_id"]=std::to_string(e.trialId);q["point_id"]=std::to_string(i);q["dedup_group"]=std::to_string(p.group);for(int a=0;a<3;++a){std::string axis(1,"xyz"[a]);q["world_"+axis]=number(p.world[a]);q["local_"+axis]=number(p.local[a]);q["normal_"+axis]=number(p.normal[a]);}q["signed_gap_m"]=number(p.gap);q["normal_impulse_Ns"]=number(p.impulse);if(p.fraction>=0)q["ccd_fraction"]=number(p.fraction);q["method"]=contactMethodName(p.method);q["candidate_source"]=p.source==ContactSource::constraint?"constraint":"ccd_resolved";q["confirmation"]="retained_confirmed";q["impulse_scope"]=p.source==ContactSource::constraint?"point_final_lambda":"manifold_shared_do_not_sum_points";q["face"]=p.face;pose(q,"rock_",p.rock);pose(q,"barrier_",p.barrier);write("barrier_first_contact_points.csv",line(points,&q));}
}
void writeAnalysisGrids(const RouteAccumulator&r,const FirstContactAccumulator&c,bool complete,const ArchiveWrite&write){
    Columns route{"cell_id","x_lower","x_upper","y_lower","y_upper","H","N","C","probability","display_value","probability_kind","lower","upper","complete"};write("route_heatmap_xy.csv",line(route));const auto&g=r.grid();
    for(size_t i=0;i<r.hits().size();++i){auto q=empty(route);auto p=g.indices(i);auto value=r.probability(r.hits()[i],complete);q["cell_id"]=std::to_string(i);q["x_lower"]=number(g.lines(0)[p[0]]);q["x_upper"]=number(g.lines(0)[p[0]+1]);q["y_lower"]=number(g.lines(1)[p[1]]);q["y_upper"]=number(g.lines(1)[p[1]+1]);q["H"]=std::to_string(r.hits()[i]);q["N"]=std::to_string(r.requested());q["C"]=std::to_string(r.completed());if(value.value)q["probability"]=number(*value.value);q["display_value"]=number(value.lower);q["probability_kind"]=value.value?"empirical_frequency":"lower_bound";q["lower"]=number(value.lower);q["upper"]=number(value.upper);q["complete"]=value.value?"1":"0";write("route_heatmap_xy.csv",line(route,&q));}
    Columns contact{"cell_id","u_lower","u_upper","v_lower","v_upper","H_b","N","C_b","B","M","unknown","probability","conditional_probability","display_value","probability_kind","lower","upper","complete","applicable"};write("barrier_first_contact_heatmap.csv",line(contact));const auto&b=c.grid();
    for(size_t i=0;i<c.hits().size();++i){auto q=empty(contact);auto p=b.indices(i);auto value=c.probability(c.hits()[i],complete);auto conditional=c.conditional(c.hits()[i],complete);q["cell_id"]=std::to_string(i);q["u_lower"]=number(b.lines(0)[p[0]]);q["u_upper"]=number(b.lines(0)[p[0]+1]);q["v_lower"]=number(b.lines(1)[p[1]]);q["v_upper"]=number(b.lines(1)[p[1]+1]);q["H_b"]=std::to_string(c.hits()[i]);q["N"]=std::to_string(c.requested());q["C_b"]=std::to_string(c.known());q["B"]=std::to_string(c.hitTrials());q["M"]=std::to_string(c.missTrials());q["unknown"]=std::to_string(c.unknown());if(value.value)q["probability"]=number(*value.value);if(conditional)q["conditional_probability"]=number(*conditional);q["probability_kind"]=!c.enabled()?"not_applicable":value.value?"empirical_frequency":"lower_bound";if(c.enabled()){q["display_value"]=number(value.lower);q["lower"]=number(value.lower);q["upper"]=number(value.upper);}q["complete"]=value.value?"1":"0";q["applicable"]=c.enabled()?"1":"0";write("barrier_first_contact_heatmap.csv",line(contact,&q));}
}
std::vector<FirstContactEvent> readFirstContacts(const std::filesystem::path&path,const BarrierSettings&b,std::uint64_t n,double cell){
    require(n>0&&n<=1000000,"first-contact directory exceeds capacity");std::vector<FirstContactEvent> out;out.resize(size_t(n));std::vector<std::uint64_t> counts(size_t(n),0);std::vector<std::size_t> cells(size_t(n),0);std::vector<Vec3> representative;representative.resize(size_t(n));
    readArchiveCsv(path/"barrier_first_contact.csv",size_t(n),[&](const CsvRow&r){auto id=archiveInteger(r.at("trial_id"));require(id>0&&id<=n&&out[size_t(id-1)].trialId==0,"duplicate/invalid first-contact trial");auto&e=out[size_t(id-1)];e.trialId=id;require(archiveInteger(r.at("barrier_id"))==barrierObjectId,"wrong first-contact barrier id");e.status=status(r.at("status"));e.trialStatus=stop(r.at("trial_status"));e.reason=r.at("reason");e.slop=archiveNumber(r.at("slop"));e.impulseThreshold=archiveNumber(r.at("impulse_threshold_Ns"));e.dedupTolerance=archiveNumber(r.at("dedup_tolerance_m"));e.boundaryTolerance=archiveNumber(r.at("boundary_tolerance_m"));
        if(e.status==FirstContactStatus::hit){e.timeLower=archiveNumber(r.at("time_lower"));e.timeUpper=archiveNumber(r.at("time_upper"));e.step=archiveInteger(r.at("step"));auto sub=archiveInteger(r.at("substep"));require(sub>=1&&sub<=4,"invalid first-contact substep");e.substep=unsigned(sub);e.u=archiveNumber(r.at("representative_u"));e.v=archiveNumber(r.at("representative_v"));e.cell=size_t(archiveInteger(r.at("cell_id")));counts[size_t(id-1)]=archiveInteger(r.at("raw_point_count"));require(counts[size_t(id-1)]>0&&counts[size_t(id-1)]<=4096,"invalid first-contact point count");e.face=r.at("face");e.rock=pose(r,"rock_");e.barrier=pose(r,"barrier_");cells[size_t(id-1)]=e.cell;representative[size_t(id-1)]={e.u,e.v,0};}
        else for(auto key:{"time_lower","time_upper","representative_u","representative_v","cell_id","rock_center_x","barrier_center_x"})require(r.at(key).empty(),"non-hit event has fabricated coordinates");});
    readArchiveCsv(path/"barrier_first_contact_points.csv",size_t(n)*4096,[&](const CsvRow&r){auto id=archiveInteger(r.at("trial_id"));require(id>0&&id<=n,"invalid point trial id");auto&e=out[size_t(id-1)];require(e.status==FirstContactStatus::hit&&archiveInteger(r.at("point_id"))==e.points.size()&&e.points.size()<counts[size_t(id-1)],"invalid first-contact point ordering/count");FirstContactPoint p;auto group=archiveInteger(r.at("dedup_group"));require(group<4096,"invalid first-contact dedup group");p.group=unsigned(group);for(int a=0;a<3;++a){std::string axis(1,"xyz"[a]);p.world[a]=archiveNumber(r.at("world_"+axis));p.local[a]=archiveNumber(r.at("local_"+axis));p.normal[a]=archiveNumber(r.at("normal_"+axis));}p.gap=archiveNumber(r.at("signed_gap_m"));p.impulse=archiveNumber(r.at("normal_impulse_Ns"));if(!r.at("ccd_fraction").empty())p.fraction=archiveNumber(r.at("ccd_fraction"));p.method=method(r.at("method"));auto source=r.at("candidate_source");require(source=="constraint"||source=="ccd_resolved","unconfirmed source in first-contact file");p.source=source=="constraint"?ContactSource::constraint:ContactSource::ccdResolved;require(r.at("confirmation")=="retained_confirmed","unconfirmed first-contact point");require(r.at("impulse_scope")== (p.source==ContactSource::constraint?"point_final_lambda":"manifold_shared_do_not_sum_points"),"incorrect impulse scope");p.face=r.at("face");p.rock=pose(r,"rock_");p.barrier=pose(r,"barrier_");e.points.push_back(p);});
    Grid3D grid({{0,0,0},{b.width,b.height,1},{cell,cell,1}});for(size_t i=0;i<out.size();++i){auto&e=out[i];require(e.trialId==i+1&&e.points.size()==counts[i],"missing first-contact trial/points");if(e.status==FirstContactStatus::noHit)require(normalCompletion(e.trialStatus),"failed trial cannot be no_hit");if(e.status==FirstContactStatus::hit){auto original=e.points;auto face=e.face;auto savedRock=e.rock,savedBarrier=e.barrier;validateFirstContact(e,b,grid);require(e.cell==cells[i]&&std::abs(e.u-representative[i].x)<1e-10&&std::abs(e.v-representative[i].y)<1e-10&&e.face==face,"first-contact representative/grid mismatch");auto samePose=[](const ContactBodyPose&a,const ContactBodyPose&b){return norm(a.center-b.center)==0&&norm(a.shapeOrigin-b.shapeOrigin)==0&&norm(a.velocity-b.velocity)==0&&norm(a.angularVelocity-b.angularVelocity)==0&&a.rotation.w==b.rotation.w&&a.rotation.x==b.rotation.x&&a.rotation.y==b.rotation.y&&a.rotation.z==b.rotation.z;};require(samePose(savedRock,e.points.front().rock)&&samePose(savedBarrier,e.points.front().barrier),"event pose differs from first raw point");for(size_t p=0;p<e.points.size();++p)require(e.points[p].group==original[p].group&&e.points[p].face==original[p].face,"first-contact dedup/face mismatch");}}
    return out;
}
}
